function test_doubleMulDivRoundingUpAccumulation() public {
    // Setup: CLOB with 200 tiny orders at a price that maximizes rounding
    // Choose sqrtPriceX96 where amountIn * sqrtPriceX96 / Q96 is not exact
    // E.g., sqrtPriceX96 = 79228162514264337593543950336 + 1 (slightly above 1:1)
    // Each order: amountIn = 3 wei
    uint256 totalPrecise = 0;
    uint256 totalRoundedUp = 0;
    uint160 price = 79228162514264337593543950337; // Q96 + 1
    for (uint256 i = 0; i < 200; i++) {
        uint256 amountIn = 3;
        uint256 step1 = FullMath.mulDivRoundingUp(amountIn, price, Q96);
        uint256 step2 = FullMath.mulDivRoundingUp(step1, price, Q96);
        totalRoundedUp += step2;
        // Precise: amountIn * price^2 / Q96^2
        totalPrecise += (amountIn * uint256(price) * uint256(price)) / (Q96 * Q96);
    }
    // Assert: totalRoundedUp > totalPrecise, difference grows with order count
    assertTrue(totalRoundedUp > totalPrecise);
    uint256 drift = totalRoundedUp - totalPrecise;
    // drift should be up to 2*200 = 400 wei in worst case
    assertTrue(drift <= 400);
    // This drift means fillOutputRemaining could underflow before all orders fill
}

