function test_computeRatioX96PrecisionLossZeroReturn() public {
    // Test: Large amount1 near type(uint256).max with moderate amount0
    // amount1 = type(uint256).max - 1
    // amount0 = type(uint256).max
    // maxMultiplier = type(uint256).max / (type(uint256).max - 1) = 1
    // While loop: n=96, multiplier=2^192 > 1, so n decreases
    //   Eventually n=0, multiplier=1, 1 <= 1, breaks
    // tmpRatio = _sqrt((type(uint256).max-1) * 1 / type(uint256).max) * 2^96
    //          = _sqrt(0) * 2^96 = 0
    // Wait: (type(uint256).max-1) / type(uint256).max = 0 in Solidity
    uint160 result = SqrtPriceCalculator.computeRatioX96(type(uint256).max - 1, type(uint256).max);
    // Result should be close to 2^96 (roughly 1:1 ratio) but may return 0
    // due to integer division truncation before sqrt

    // More practical case: amount1 = 1, amount0 = type(uint256).max
    // maxMultiplier = type(uint256).max / 1 = type(uint256).max
    // n = 96 (2^192 <= type(uint256).max)
    // tmpRatio = _sqrt(1 * 2^192 / type(uint256).max) * 2^0
    //          = _sqrt(2^192 / 2^256) = _sqrt(0) = 0
    result = SqrtPriceCalculator.computeRatioX96(1, type(uint256).max);
    // This should return MIN_SQRT_RATIO but may return 0
    // In validateHandlerOrder, 0 < maxSqrtPriceX96 -> passes max check
    assertEq(result, 0); // If true, validateHandlerOrder has a bypass
}

