function test_computeRatioX96UnderflowToZero() public {
    // Test: amount1 near type(uint256).max, amount0 = type(uint256).max
    // maxMultiplier = type(uint256).max / (type(uint256).max - 1) = 1
    // n=0, multiplier=1
    // tmpRatio = _sqrt((type(uint256).max-1) * 1 / type(uint256).max) * 2^96
    //          = _sqrt(0) * 2^96 = 0
    uint160 result = SqrtPriceCalculator.computeRatioX96(
        type(uint256).max - 1, type(uint256).max
    );
    // Should be ~2^96 (1:1 ratio) but returns 0 due to integer truncation

    // More practical: amount1=1, amount0=1e36
    // maxMultiplier = type(uint256).max / 1 -> very large, n=96
    // tmpRatio = _sqrt(1 * 2^192 / 1e36) * 2^0
    //          = _sqrt(2^192 / 1e36)
    // 2^192 ~ 6.27e57, / 1e36 = 6.27e21
    // sqrt(6.27e21) ~ 7.9e10
    // This is non-zero, fine.

    // Edge case: amount1=1, amount0=type(uint256).max
    // n=96, tmpRatio = _sqrt(2^192 / type(uint256).max) * 2^0
    //               = _sqrt(~0) = 0
    result = SqrtPriceCalculator.computeRatioX96(1, type(uint256).max);
    assertEq(result, 0); // Zero price bypasses max bounds

    // In validateHandlerOrder with bounds.maxSqrtPriceX96 set:
    // 0 > maxSqrtPriceX96 is false -> passes! Zero price order accepted
}

function test_cumulativeRoundingInFillOrder() public {
    // Setup: CLOB with 200 orders at price that maximizes rounding
    // sqrtPriceX96 = Q96 + 1 (slightly above 1:1)
    // Each order: inputAmount = 3 wei (minimum that shows rounding)
    uint256 totalRounded = 0;
    uint256 totalExact = 0;
    uint160 price = uint160((1 << 96) + 1);
    uint256 Q96 = 1 << 96;
    for (uint256 i = 0; i < 200; i++) {
        uint256 step1 = FullMath.mulDivRoundingUp(3, price, Q96);
        uint256 step2 = FullMath.mulDivRoundingUp(step1, price, Q96);
        totalRounded += step2;
    }
    // Compare with bulk calculation
    uint256 bulkStep1 = FullMath.mulDivRoundingUp(600, price, Q96);
    uint256 bulkStep2 = FullMath.mulDivRoundingUp(bulkStep1, price, Q96);
    // totalRounded > bulkStep2 (accumulated rounding per order)
